#include <filesystem>
#include <iostream>
#include <stdexcept>
#include "hms/AppContext.h"
#include "hms/Security.h"
using namespace hms;
static int passed=0,failed=0;
#define CHECK(x) do{if(!(x))throw std::runtime_error("CHECK failed: " #x);}while(0)
template<class F>void test(const char*n,F f){try{f();++passed;std::cout<<"[PASS] "<<n<<"\n";}catch(const std::exception&e){++failed;std::cout<<"[FAIL] "<<n<<": "<<e.what()<<"\n";}}
int main(){
 test("password hash verifies and is not plaintext",[]{auto h=hashPassword("correct horse");CHECK(h!="correct horse");CHECK(verifyPassword("correct horse",h));CHECK(!verifyPassword("wrong",h));});
 test("authentication registration, duplicate and login",[]{Auth a;CHECK(a.registerUser("admin","secret12",Role::Admin));CHECK(!a.registerUser("admin","secret12",Role::Admin));CHECK(!a.login("admin","bad"));CHECK(a.login("admin","secret12"));CHECK(a.hasRole(Role::Admin));a.logout();CHECK(!a.isLoggedIn());});
 test("patient register, id, search and update",[]{PatientManager p;Patient d;d.name="Alice Doe";d.age=25;d.phone="999";auto r=p.registerPatient(d);CHECK(r&&r.value.id==1);CHECK(p.exists(1));CHECK(p.searchByName("alice").size()==1);auto x=*p.findById(1);x.address="Bangalore";CHECK(p.updatePatient(x));CHECK(p.findById(1)->address=="Bangalore");});
 test("patient rejects duplicate phone and invalid details",[]{PatientManager p;Patient d;d.name="A";d.phone="1";CHECK(p.registerPatient(d));CHECK(!p.registerPatient(d));d.phone="2";d.age=200;CHECK(!p.registerPatient(d));});
 test("doctor add/update/availability",[]{DoctorManager d;Doctor x;x.name="Dr X";x.specialization="Cardiology";auto r=d.addDoctor(x);CHECK(r&&r.value.id==1);CHECK(d.worksAt(1,{"2026-11-05","10:00"}));CHECK(!d.worksAt(1,{"2026-11-05","1A:00"}));CHECK(d.setAvailability(1,false));CHECK(!d.worksAt(1,{"2026-11-05","10:00"}));});
 test("appointment book prevents double booking",[]{PatientManager p;Patient x;x.name="P";x.phone="1";auto pr=p.registerPatient(x);DoctorManager d;Doctor y;y.name="D";y.specialization="General";auto dr=d.addDoctor(y);AppointmentManager a(p,d);auto r=a.book(pr.value.id,dr.value.id,{"2026-11-05","10:00"},"Checkup");CHECK(r);CHECK(!a.book(pr.value.id,dr.value.id,{"2026-11-05","10:00"},"Other"));});
 test("appointment rejects invalid patient/doctor/work hours",[]{PatientManager p;DoctorManager d;Doctor y;y.name="D";y.specialization="General";auto dr=d.addDoctor(y);AppointmentManager a(p,d);CHECK(!a.book(55,dr.value.id,{"2026-11-05","10:00"},"x"));Patient x;x.name="P";x.phone="2";auto pr=p.registerPatient(x);CHECK(!a.book(pr.value.id,dr.value.id,{"2026-11-05","18:00"},"x"));});
 test("appointment cancellation frees slot",[]{PatientManager p;Patient x;x.name="P";x.phone="1";auto pr=p.registerPatient(x);DoctorManager d;Doctor y;y.name="D";y.specialization="General";auto dr=d.addDoctor(y);AppointmentManager a(p,d);auto b=a.book(pr.value.id,dr.value.id,{"2026-11-05","10:00"},"x");CHECK(b);CHECK(a.cancel(b.value.id));CHECK(a.isSlotFree(dr.value.id,{"2026-11-05","10:00"}));});
 test("appointment reschedule blocks collisions",[]{PatientManager p;Patient x;x.name="P1";x.phone="1";auto p1=p.registerPatient(x);x.name="P2";x.phone="2";auto p2=p.registerPatient(x);DoctorManager d;Doctor y;y.name="D";y.specialization="General";auto dr=d.addDoctor(y);AppointmentManager a(p,d);auto b=a.book(p1.value.id,dr.value.id,{"2026-11-05","10:00"},"x");auto c=a.book(p2.value.id,dr.value.id,{"2026-11-05","11:00"},"x");CHECK(b&&c);CHECK(!a.reschedule(c.value.id,{"2026-11-05","10:00"}));CHECK(a.reschedule(c.value.id,{"2026-11-05","12:00"}));});
 test("billing invoice and payment",[]{Billing b;auto i=b.createInvoice(1,0,125050,"Consultation");CHECK(i);CHECK(b.outstandingCents(1)==125050);CHECK(b.markPaid(i.value.id));CHECK(b.outstandingCents(1)==0);});
 test("persistence survives restart",[]{auto dir=std::filesystem::temp_directory_path()/"hms_test_persistence";std::filesystem::remove_all(dir);FileHandler f(dir.string());Auth a;CHECK(a.registerUser("root","password1",Role::Admin));PatientManager p;Patient x;x.name="Test";x.phone="123";CHECK(p.registerPatient(x));DoctorManager d;Doctor z;z.name="Dr";z.specialization="General";CHECK(d.addDoctor(z));CHECK(f.saveUsers(a.all()));CHECK(f.savePatients(p.all()));CHECK(f.saveDoctors(d.all()));std::vector<User>u;std::vector<Patient>ps;std::vector<Doctor>ds;CHECK(f.loadUsers(u));CHECK(f.loadPatients(ps));CHECK(f.loadDoctors(ds));CHECK(u.size()==1&&ps.size()==1&&ds.size()==1);std::filesystem::remove_all(dir);});
 test("report generation",[]{PatientManager p;Patient x;x.name="Report Patient";x.phone="111";auto pr=p.registerPatient(x);DoctorManager d;Doctor z;z.name="Doctor";z.specialization="General";auto dr=d.addDoctor(z);AppointmentManager a(p,d);CHECK(a.book(pr.value.id,dr.value.id,{"2026-11-05","10:00"},"Review"));Billing b;ReportManager r(p,d,a,b);CHECK(r.patientReport(pr.value.id).ok());CHECK(r.appointmentReport("2026-11-05").find("Report Patient")!=std::string::npos);CHECK(r.doctorScheduleReport(dr.value.id).ok());});
 test("missing storage files load as empty",[]{auto dir=std::filesystem::temp_directory_path()/"hms_missing_files";std::filesystem::remove_all(dir);FileHandler f(dir.string());std::vector<User>u;CHECK(f.loadUsers(u));CHECK(u.empty());std::filesystem::remove_all(dir);});
 std::cout<<"\nPassed: "<<passed<<" Failed: "<<failed<<"\n";return failed?1:0;
}
